#!/usr/bin/env bash
set -Eeuo pipefail

script_path="$(readlink -f "${BASH_SOURCE[0]}")"
driver_root="$(cd "$(dirname "$script_path")/../../.." && pwd)"

run_as_root() {
  local env_file="$1" task_home="" result=0
  [[ "$EUID" == 0 ]] || { echo "Internal mock runner requires sudo" >&2; exit 2; }
  [[ -r "$env_file" ]] || { echo "Missing temporary test environment" >&2; exit 2; }
  # Generated by this script with mode 0600; includes the API key.
  # shellcheck disable=SC1090
  source "$env_file"
  rm -f "$env_file"

  mkdir -p "$HOME/.cache/ngxstorage"
  task_home="$(mktemp -d "$HOME/.cache/ngxstorage/fc-sanity.XXXXXX")"
  export HOME="$task_home" TMPDIR="$task_home/.cache/ngxstorage"
  export GOCACHE="$TMPDIR/go-cache"
  export PATH="$(dirname "$FC_GO_BIN"):/usr/local/bin:/usr/bin:/bin"
  export GOROOT="$FC_GOROOT" GOPATH="$FC_GOPATH" GOMODCACHE="$FC_GOMODCACHE"
  mkdir -p "$TMPDIR" "$GOCACHE"

  local -a host_link_paths=() host_link_ids=() host_link_targets=()

  cleanup_root() {
    # Preserve pre-existing paths and links replaced by another process.
    local host_index
    for ((host_index=${#host_link_paths[@]}-1; host_index>=0; host_index--)); do
      local created_path="${host_link_paths[host_index]}"
      if [[ -L "$created_path" &&
            "$(readlink -- "$created_path")" == "${host_link_targets[host_index]}" &&
            "$(stat -c '%d:%i' -- "$created_path")" == "${host_link_ids[host_index]}" ]]; then
        rm -- "$created_path"
      fi
    done
    local mounts=""
    if command -v findmnt >/dev/null 2>&1; then
      mounts="$(findmnt -rn -o TARGET | awk -v prefix="$task_home/" 'index($0, prefix) == 1')"
    fi
    if [[ -n "$mounts" ]]; then
      echo "Keeping temporary home because test mounts remain:" >&2
      printf '%s\n' "$mounts" >&2
    else
      rm -rf -- "$task_home"
    fi
  }
  trap cleanup_root EXIT

  # /host is normally the Kubernetes hostPath mount. Standalone tests
  # expose missing paths with symlinks, preserving existing host data/mounts.
  command -v flock >/dev/null || { echo "Local sanity requires flock" >&2; exit 2; }
  mkdir -p /run/lock
  exec 9>/run/lock/ngxstorage-csi-local-host.lock
  echo "Waiting for the local CSI host-root lock..."
  flock -x 9
  add_host_link() {
    local link_path="$1" link_target="$2"
    if [[ ! -e "$link_path" && ! -L "$link_path" ]]; then
      ln -sT -- "$link_target" "$link_path"
      host_link_paths+=("$link_path")
      host_link_ids+=("$(stat -c '%d:%i' -- "$link_path")")
      host_link_targets+=("$link_target")
      printf 'Created %s -> %s for local sanity.\n' "$link_path" "$link_target"
    fi
  }
  add_host_link /host /
  [[ -d /host ]] || { echo "Existing /host is not a usable directory" >&2; exit 2; }
  add_host_link /host/etc /etc
  add_host_link /host/sys /sys
  [[ -d /host/etc && -d /host/sys ]] || {
    echo "Existing /host/etc or /host/sys is not a usable directory" >&2
    exit 2
  }


  export FC_LIVE_MOCK_SANITY=1 FC_SANITY_BIN="${CSI_SANITY_BIN:?shared csi-sanity binary path not resolved by the dispatcher}"
  export FC_SANITY_CONFIG_DIR="$driver_root/tests/sanity/local"
  local timeout=65m
  if [[ -n "${SANITY_FOCUS_FILE:-}" ]]; then
    unset SANITY_FULL
    timeout=10m
    echo "Running one focused FC csi-sanity spec with process-local test coordination."
  else
    export SANITY_FULL=1
    echo "Running the complete FC csi-sanity suite with process-local test coordination; no Kubernetes Lease or cross-process fencing."
  fi
  local log_dir="$driver_root/tests/sanity/local/logs"
  local log_file="$log_dir/mock-$(date +%Y%m%d-%H%M%S)-$$.log"
  mkdir -p "$log_dir"
  printf 'FC csi-sanity log: %s\n' "$log_file"
  set +e
  (cd "$driver_root" && "$FC_GO_BIN" test -timeout "$timeout" ./pkg/driver -run '^TestLocalSanityWithMockCoordination$' -count=1 -v) 2>&1 | tee "$log_file"
  result="${PIPESTATUS[0]}"
  set -e
  printf '\nFC csi-sanity exit code: %s\nLog: %s\n' "$result" "$log_file"
  exit "$result"
}

if [[ "${1:-}" == --as-root ]]; then
  [[ $# == 2 ]] || { echo "Internal invocation error" >&2; exit 2; }
  run_as_root "$2"
fi

user_tmp="$HOME/.cache/ngxstorage"
mkdir -p "$user_tmp"
env_file="$(mktemp "$user_tmp/fc-sanity-env.XXXXXX")"
chmod 600 "$env_file"
trap 'rm -f "$env_file"' EXIT
export FC_GO_BIN="$(command -v go)"
export FC_GOROOT="$(go env GOROOT)" FC_GOPATH="$(go env GOPATH)" FC_GOMODCACHE="$(go env GOMODCACHE)"
echo "Checking FC backend before requesting sudo..."
FC_LIVE_MOCK_PREFLIGHT=1 "$FC_GO_BIN" test ./pkg/driver -run '^TestLocalSanityBackendPreflight$' -count=1
python3 - "$env_file" <<'PY'
from pathlib import Path
import os
import shlex
import sys

keys = (
    "STORAGE_API_KEY", "STORAGE_IPS", "STORAGE_POOL_NAME", "STORAGE_FC_TARGET_NAMES", "CSI_SANITY_BIN",
    "SANITY_FOCUS_FILE", "SANITY_SKIP_TESTS", "FC_GO_BIN", "FC_GOROOT", "FC_GOPATH", "FC_GOMODCACHE",
)
values = {key: os.environ.get(key, "") for key in keys}
missing = [key for key, value in values.items() if not value and key not in ("SANITY_FOCUS_FILE", "SANITY_SKIP_TESTS")]
if missing:
    raise SystemExit("Missing required settings: " + ", ".join(missing))
Path(sys.argv[1]).write_text("".join(f"export {key}={shlex.quote(value)}\n" for key, value in values.items()))
PY
sudo -E bash "$script_path" --as-root "$env_file"
